export const messages: Record<DisplayLanguage, Record<MessageKey, string>> = { en, 'zh-CN': zhCN };

export function interpolate(template: string, params: MessageParams = {}): string {
  return template.replace(/\{([a-zA-Z][\w]*)\}/g, (_, key: string) => {
    if (!(key in params)) {
      if (typeof process !== 'undefined' && process.env.NODE_ENV === 'test') {
        throw new Error(`Missing interpolation parameter: ${key}`);
      }
      return `{${key}}`;
    }
    return String(params[key]);
  });
}

export function translateMessage(language: DisplayLanguage, key: MessageKey, params?: MessageParams): string {
  const template = messages[language][key] ?? messages.en[key] ?? key;
  return interpolate(template, params);
}
